<script setup>
import RichText from './RichText.vue'
const props=defineProps({modelValue:{},disabled:Boolean,path:{type:String,default:''},deltas:Object})
const emit=defineEmits(['update:modelValue','rich-change'])
const labels={target_audience:'目标客群',price_band_analysis:'价格带分析',selling_point_matrix:'卖点矩阵',selling_point:'卖点',evidence:'依据',recommendation:'建议',conversion_bottlenecks:'转化卡点',optimization_directions:'优化方向',image_directions:'主图方向',video_scripts:'视频脚本',selection_id:'方案编码',title:'方案名称',layout:'构图版式',core_copy:'核心文案',main_selling_point:'主打卖点',visual_advice:'视觉建议',hook_3s:'开头三秒钩子',shots:'分镜',scene_description:'画面描述',voiceover:'口播台词',cta:'促单话术',strategy:'投放策略',groups:'A/B 实验组',group_code:'组别编码',material_ids:'素材编号',audience:'人群',audience_packages:'推荐人群包',bid:'出价（元）',budget:'预算（元）',description:'说明',targets:'指标目标',ctr:'CTR（比例）',conversion_rate:'转化率（比例）',roi:'广告投入产出比（倍）',detail_bounce_rate:'详情页跳失率（比例）',date_from:'开始日期',date_to:'结束日期',sections:'报告五部分',product_overview:'单品全景信息',diagnosis_summary:'智能诊断总结',content_assets:'视觉与内容资产',experiment_record:'投放实验记录',performance_review:'经营复盘与后评价',summary:'摘要',facts:'已验证指标',hypotheses:'归因推测',evidence_gaps:'证据缺口',actions:'优化行动',action_id:'行动编码',verification_method:'验证方法'}
const hidden=new Set(['generation_mode','selected_image_ids','selected_video_ids','approval','product_id','experiment_id','creative_content_id','diagnosis_content_id','shop_id','proposal_key','version','status','id','content_confirmed'])
function change(key,value){const next=Array.isArray(props.modelValue)?[...props.modelValue]:{...props.modelValue};next[key]=value;emit('update:modelValue',next)}
function add(){const sample=props.modelValue[0];let value=typeof sample==='object'&&sample!==null?JSON.parse(JSON.stringify(sample)):typeof sample==='number'?0:'';if(value&&typeof value==='object'){for(const key of Object.keys(value))if(typeof value[key]==='string')value[key]=''}emit('update:modelValue',[...props.modelValue,value])}
function remove(index){emit('update:modelValue',props.modelValue.filter((_x,i)=>i!==index))}
</script>
<template>
 <div v-if="Array.isArray(modelValue)" class="value-list"><div v-for="(value,index) in modelValue" :key="index" class="editor-item"><ValueEditor :model-value="value" :deltas="deltas" :disabled="disabled" :path="`${path}.${index}`" @update:model-value="change(index,$event)" @rich-change="(p,d)=>emit('rich-change',p,d)"/><button v-if="!disabled" type="button" class="subtle" @click="remove(index)">移除</button></div><button v-if="!disabled" class="subtle" type="button" @click="add">＋ 添加一项</button></div>
 <div v-else-if="modelValue&&typeof modelValue==='object'" class="value-object"><template v-for="(value,key) in modelValue" :key="key"><label v-if="!hidden.has(key)" class="field"><span>{{labels[key]||key}}</span><RichText v-if="typeof value==='string'&&['core_copy','voiceover'].includes(key)" :model-value="value" :delta="deltas?.[`${path}.${key}`]" :disabled="disabled" @update:model-value="change(key,$event)" @delta="emit('rich-change',`${path}.${key}`,$event)"/><ValueEditor v-else :model-value="value" :deltas="deltas" :disabled="disabled" :path="`${path}.${key}`" @update:model-value="change(key,$event)" @rich-change="(p,d)=>emit('rich-change',p,d)"/></label></template></div>
 <input v-else-if="typeof modelValue==='number'" type="number" step="any" :value="modelValue" :disabled="disabled" @input="emit('update:modelValue',$event.target.value===''?null:Number($event.target.value))">
 <textarea v-else :value="modelValue??''" :disabled="disabled" rows="2" @input="emit('update:modelValue',$event.target.value)"></textarea>
</template>
